const [lastMealTime, setLastMealTime] = useState('');

const validateLastMeal = () => {
  if (lastMealTime && firstMealTime) {
    const [fh, fm] = firstMealTime.split(':').map(Number);
    const [lh, lm] = lastMealTime.split(':').map(Number);
    if (lh * 60 + lm <= fh * 60 + fm) {
      setErrors({ lastMealTime: 'Must be after first meal' });
    }
  }
};

return (
  <TimeInput
    id="last-meal-time"
    label="Last Meal Time"
    value={lastMealTime}
    onChange={setLastMealTime}
    onBlur={validateLastMeal}
    error={errors.lastMealTime}
    required={true}
  />
);

